import 'dart:async';

import 'package:flutter/services.dart' show AssetManifest, rootBundle;
import 'package:just_audio/just_audio.dart';

import 'clips.dart';
import 'device_voice.dart';
import 'voice_io.dart';

/// Premium narration: plays the professionally voiced clip bundled for each
/// line (generated by `tool/generate_audio.dart`). Clips ship inside the app,
/// so narration needs no connection while driving. Any line without a clip
/// falls back to the phone's own voice. Listening always uses the device.
class PremiumVoice implements VoiceIO {
  PremiumVoice(this.lang, this.device);

  final String lang;
  final DeviceVoice device;
  final AudioPlayer _player = AudioPlayer();
  Set<String> _clips = const {};
  bool _stopped = false;
  double _rate = 1.0;

  /// How many bundled clips exist for this language (0 = device voice only).
  int get clipCount => _clips.length;

  @override
  Future<void> init(String speechLocale) async {
    await device.init(speechLocale);
    try {
      final manifest = await AssetManifest.loadFromAssetBundle(rootBundle);
      _clips = manifest.listAssets().where((a) => a.startsWith('assets/audio/$lang/')).toSet();
    } catch (_) {
      _clips = const {};
    }
  }

  @override
  Future<void> speak(String text) async {
    final asset = clipAsset(lang, text);
    if (!_clips.contains(asset)) return device.speak(text);
    _stopped = false;
    try {
      await _player.setAsset(asset);
      if (_stopped) return;
      if (_player.speed != _rate) await _player.setSpeed(_rate);
      await _player.play(); // completes when the clip ends or is stopped
    } catch (_) {
      if (!_stopped) await device.speak(text);
    }
  }

  @override
  Future<void> setRate(double rate) async {
    _rate = rate;
    await _player.setSpeed(rate); // time-stretched, pitch stays natural
    await device.setRate(rate);
  }

  @override
  Future<void> stopSpeaking() async {
    _stopped = true;
    await _player.stop();
    await device.stopSpeaking();
  }

  @override
  Future<List<String>?> listen({
    Duration timeout = const Duration(seconds: 9),
    bool Function(List<String>)? acceptEarly,
    List<String> hints = const [],
  }) =>
      device.listen(timeout: timeout, acceptEarly: acceptEarly, hints: hints);

  @override
  Future<void> cancelListening() => device.cancelListening();
}
